/**
 * PNG copies (200 x 200) of the built-in stamp icons, for the server-side
 * wallet picture renderer, which cannot fetch /stamp-icons/3d/*.webp. Generated
 * from the same Fluent Emoji 3D files (MIT, Microsoft) - see stamp-icons.ts.
 * Only the wallet picture route imports this, so it never reaches the browser.
 */
import { findStampIcon } from "@/lib/wallet/stamp-icons";

