/** The built-in icon for an emoji as a data: URL the PNG renderer can embed. */
export function stampIconDataUrl(emoji: string | null | undefined): string {
  return `data:image/png;base64,${STAMP_ICON_PNG_BASE64[findStampIcon(emoji).file]}`;
}
